/** Synchronous, injectable subset of Creator sys.localStorage; no cc/global dependency. */
export interface StoragePort {
    getItem(key: string): string | null;
    setItem(key: string, value: string): void;
    removeItem(key: string): void;
}

export const BEST_SCORE_KEY = 'jump:4856b445-bfe4-49c2-8933-59e229f06792:best:v1';

/** Best score belongs to this project only. Storage failure never aborts a run. */
export class StorageAdapter {
    readonly key: string = BEST_SCORE_KEY;
    private value = 0;
    private error: string | null = null;
    private pendingWrite = false;

    constructor(private readonly storage: StoragePort) {
        let raw: string | null;
        try { raw = storage.getItem(this.key); }
        catch (_) { this.error = 'storage-read-failed'; return; }
        if (raw === null) return;
        try {
            const parsed: unknown = JSON.parse(raw);
            if (!this.validScore(parsed)) { this.error = 'invalid-stored-score'; return; }
            this.value = parsed;
        } catch (_) { this.error = 'invalid-stored-score'; }
    }

    get best(): number { return this.value; }
    get lastError(): string | null { return this.error; }

    /** true means the current max needs no further write, not that score increased. */
    record(score: number): boolean {
        if (!this.validScore(score)) { this.error = 'invalid-score'; return false; }
        if (score > this.value) { this.value = score; this.pendingWrite = true; }
        if (!this.pendingWrite) return true;
        try {
            this.storage.setItem(this.key, JSON.stringify(this.value));
            this.pendingWrite = false; this.error = null;
            return true;
        } catch (_) { this.error = 'storage-write-failed'; return false; }
    }

    /** Failed removal retains memory/pending state; callers must inspect the result. */
    reset(): boolean {
        try { this.storage.removeItem(this.key); }
        catch (_) { this.error = 'storage-remove-failed'; return false; }
        this.value = 0; this.pendingWrite = false; this.error = null;
        return true;
    }

    private validScore(score: unknown): score is number {
        return typeof score === 'number' && Number.isFinite(score) && Number.isInteger(score) && score >= 0;
    }
}

import { StorageAdapter, StoragePort, BEST_SCORE_KEY } from '../../assets/scripts/jump/adapters/StorageAdapter';
import { JumpGameplay, RunStateMachine, JumpPlanDraft, RunCommand, JumpToken, DEFAULT_GAME_CONFIG as C } from '../../assets/scripts/jump/core';
declare const require: (name: string) => any;
declare const process: any;
const fs = require('fs'), crypto = require('crypto'), os = require('os');
const cases: any[] = [];
let assertions = 0;
function assert(value: unknown, message: string): asserts value {
    assertions++; if (!value) throw new Error(message);
}
function eq(actual: unknown, expected: unknown, message = 'equality'): void {
    assert(JSON.stringify(actual) === JSON.stringify(expected), `${message}: ${JSON.stringify(actual)} != ${JSON.stringify(expected)}`);
}
function test(caseId: string, expected: string, run: () => unknown): void {
    const before = assertions;
    try {
        const actual = run(); cases.push({ caseId, expected, actual: actual === undefined ? 'all assertions passed' : actual,
            status: 'pass', assertions: assertions - before }); console.log(`PASS ${caseId}`);
    } catch (e) {
        const actual = e instanceof Error ? e.message : String(e);
        cases.push({ caseId, expected, actual, status: 'fail', assertions: assertions - before }); console.error(`FAIL ${caseId}: ${actual}`);
    }
}
/** A fault-injected storage port, not a replacement for the production adapter. */
class MemoryStorage implements StoragePort {
    readonly values = new Map<string, string>();
    readonly calls: { operation: string; key: string; value?: string }[] = [];
    failGet = false; failSet = false; failRemove = false;
    constructor(raw: string | null = null) { if (raw !== null) this.values.set(BEST_SCORE_KEY, raw); }
    getItem(key: string): string | null {
        this.calls.push({ operation: 'get', key }); if (this.failGet) throw new Error('injected get');
        return this.values.has(key) ? this.values.get(key)! : null;
    }
    setItem(key: string, value: string): void {
        this.calls.push({ operation: 'set', key, value }); if (this.failSet) throw new Error('injected set');
        this.values.set(key, value);
    }
    removeItem(key: string): void {
        this.calls.push({ operation: 'remove', key }); if (this.failRemove) throw new Error('injected remove');
        this.values.delete(key);
    }
}

test('R13-namespace-missing', 'fixed package namespace, missing=0, read-only construction, no network', () => {
